//! Host-only volume: an output-stream gain, never a change to the emulated SPU or WAVs.
//! Generated by Codex (GPT-6.1 sol).
use std::path::{Path, PathBuf};

pub mod macos;
pub mod preview;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Volume {
    // Keep the last audible level while muted, including when the slider reaches zero.
    level: u8,
    muted: bool,
}
impl Default for Volume {
    fn default() -> Self {
        Self {
            level: 100,
            muted: false,
        }
    }
}
impl Volume {
    pub fn percent(self) -> u8 {
        if self.muted { 0 } else { self.level }
    }
    pub fn gain(self) -> f32 {
        f32::from(self.percent()) / 100.0
    }
    fn at(self, percent: u8) -> Result<Self, String> {
        match percent {
            0 => Ok(Self {
                muted: true,
                ..self
            }),
            1..=100 => Ok(Self {
                level: percent,
                muted: false,
            }),
            _ => Err("Volume must be between 0 and 100.".into()),
        }
    }
    fn toggled(self) -> Self {
        Self {
            muted: !self.muted,
            ..self
        }
    }
    fn json(self) -> serde_json::Value {
        serde_json::json!({"version":1, "volume":self.level, "muted":self.muted})
    }
    fn parse(text: &str) -> Result<Self, String> {
        let v: serde_json::Value = serde_json::from_str(text).map_err(|e| e.to_string())?;
        if v["version"].as_u64() != Some(1) {
            return Err("Unsupported sound file version.".into());
        }
        let level = v["volume"]
            .as_u64()
            .filter(|v| (1..=100).contains(v))
            .ok_or("Stored volume must be between 1 and 100 (mute stores silence separately).")?;
        let muted = v["muted"].as_bool().ok_or("Missing mute setting.")?;
        Ok(Self {
            level: level as u8,
            muted,
        })
    }
}

pub struct State {
    pub volume: Volume,
    path: Option<PathBuf>,
    dirty: bool,
    pub error: String,
}
impl State {
    pub fn load() -> Self {
        let path = std::env::var_os("DW1_SOUND_FILE")
            .map(PathBuf::from)
            .or_else(|| crate::default_save_dir().map(|p| p.join("sound.json")));
        Self::at(path)
    }
    fn at(path: Option<PathBuf>) -> Self {
        let mut s = Self {
            volume: Volume::default(),
            path,
            dirty: false,
            error: String::new(),
        };
        if let Some(path) = &s.path {
            match std::fs::read_to_string(path) {
                Ok(text) => match Volume::parse(&text) {
                    Ok(v) => s.volume = v,
                    Err(e) => {
                        s.error = format!(
                            "Could not load sound settings: {e} Defaults are in use; the file is unchanged."
                        )
                    }
                },
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                Err(e) => s.error = format!("Could not read sound settings: {e}"),
            }
        }
        s
    }
    pub fn change(&mut self, percent: u8, apply: impl FnOnce(f32) -> Result<(), String>) {
        match self.volume.at(percent) {
            Ok(v) => {
                self.accept(v, apply);
            }
            Err(e) => self.error = e,
        }
    }
    pub fn toggle(&mut self, apply: impl FnOnce(f32) -> Result<(), String>) {
        if self.accept(self.volume.toggled(), apply) {
            self.commit();
        }
    }
    fn accept(&mut self, next: Volume, apply: impl FnOnce(f32) -> Result<(), String>) -> bool {
        if let Err(e) = apply(next.gain()) {
            self.error = format!("Could not change output volume: {e}");
            return false;
        }
        self.dirty |= self.volume != next;
        self.volume = next;
        self.error.clear();
        true
    }
    // The gain changes on every input; persistence happens on release/keyboard change/close.
    // A write failure never undoes an audible adjustment or silently claims it was saved.
    pub fn commit(&mut self) {
        if !self.dirty {
            return;
        }
        let result = self
            .path
            .as_deref()
            .ok_or_else(|| "No preferences folder available.".to_string())
            .and_then(|p| save(p, self.volume));
        match result {
            Ok(()) => {
                self.dirty = false;
                self.error.clear();
            }
            Err(e) => self.error = format!("Volume changed, but could not save: {e}"),
        }
    }
    pub fn view(&self, available: bool) -> String {
        serde_json::json!({"percent":self.volume.percent(), "restore":self.volume.level,
            "muted":self.volume.muted, "available":available, "error":self.error})
        .to_string()
    }
}
fn save(path: &Path, v: Volume) -> Result<(), String> {
    let tmp = path.with_extension(format!("{}.tmp", std::process::id()));
    let result = (|| -> std::io::Result<()> {
        if let Some(parent) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(&tmp, format!("{}\n", v.json()))?;
        std::fs::rename(&tmp, path)
    })();
    if result.is_err() {
        let _ = std::fs::remove_file(&tmp);
    }
    result.map_err(|e| e.to_string())
}

#[derive(Debug, PartialEq)]
pub enum Action {
    Ready,
    Volume(u8),
    Mute,
    Commit,
    Done,
}
pub fn action(text: &str) -> Option<Action> {
    let v: serde_json::Value = serde_json::from_str(text).ok()?;
    Some(match v["action"].as_str()? {
        "ready" => Action::Ready,
        "volume" => Action::Volume(
            v["percent"]
                .as_u64()?
                .try_into()
                .ok()
                .filter(|v| *v <= 100)?,
        ),
        "mute" => Action::Mute,
        "commit" => Action::Commit,
        "done" => Action::Done,
        _ => return None,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    fn temporary() -> PathBuf {
        std::env::temp_dir().join(format!(
            "dw1-sound-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ))
    }
    #[test]
    fn default_is_original_output_and_mute_restores_level() {
        let v = Volume::default();
        assert_eq!(v.gain(), 1.0);
        let v = v.at(37).unwrap();
        assert_eq!(v.percent(), 37);
        let v = v.toggled();
        assert_eq!(v.gain(), 0.0);
        assert_eq!(v.toggled().percent(), 37);
        let v = v.toggled().at(0).unwrap();
        assert_eq!(v.percent(), 0);
        assert_eq!(v.toggled().percent(), 37);
        assert_eq!(v.at(24).unwrap().percent(), 24);
        assert!(v.at(101).is_err());
    }
    #[test]
    fn all_slider_values_are_bounded_and_round_trip() {
        for n in 0..=100 {
            let v = Volume::default().at(n).unwrap();
            assert_eq!(v.percent(), n);
            assert!((0.0..=1.0).contains(&v.gain()));
            assert_eq!(Volume::parse(&v.json().to_string()).unwrap(), v);
        }
    }
    #[test]
    fn malformed_files_fail_closed() {
        for text in [
            "{}",
            "null",
            "[]",
            "{\"version\":2,\"volume\":50,\"muted\":false}",
            "{\"version\":1,\"volume\":0,\"muted\":false}",
            "{\"version\":1,\"volume\":101,\"muted\":false}",
            "{\"version\":1,\"volume\":50.5,\"muted\":false}",
            "{\"version\":1,\"volume\":-1,\"muted\":false}",
            "{\"version\":1,\"volume\":50,\"muted\":\"yes\"}",
        ] {
            assert!(Volume::parse(text).is_err(), "{text}");
        }
    }
    #[test]
    fn live_change_precedes_commit_and_survives_reload() {
        let dir = temporary();
        let path = dir.join("sound.json");
        let mut s = State::at(Some(path.clone()));
        let mut gains = Vec::new();
        s.change(43, |g| {
            gains.push(g);
            Ok(())
        });
        assert_eq!(gains, vec![0.43]);
        assert!(!path.exists());
        s.commit();
        assert!(s.error.is_empty());
        assert_eq!(State::at(Some(path.clone())).volume.percent(), 43);
        s.change(0, |_| Ok(()));
        s.commit();
        let s = State::at(Some(path));
        assert_eq!(s.volume.percent(), 0);
        assert_eq!(s.volume.toggled().percent(), 43);
        std::fs::remove_dir_all(dir).unwrap();
    }
    #[test]
    fn malformed_loading_does_not_overwrite_and_errors_are_visible() {
        let dir = temporary();
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("sound.json");
        std::fs::write(&path, "not json").unwrap();
        let mut s = State::at(Some(path.clone()));
        assert_eq!(s.volume, Volume::default());
        assert!(!s.error.is_empty());
        s.commit();
        assert_eq!(std::fs::read_to_string(path).unwrap(), "not json");
        std::fs::remove_dir_all(dir).unwrap();
    }
    #[test]
    fn output_failure_leaves_volume_unchanged() {
        let mut s = State::at(None);
        s.change(22, |_| Err("device failure".into()));
        assert_eq!(s.volume, Volume::default());
        assert!(!s.dirty);
        assert!(s.error.contains("device failure"));
    }
    #[test]
    fn save_failure_keeps_live_gain_and_previous_file() {
        let dir = temporary();
        std::fs::create_dir_all(&dir).unwrap();
        let parent = dir.join("not-a-folder");
        std::fs::write(&parent, "keep me").unwrap();
        let mut s = State::at(Some(parent.join("sound.json")));
        s.change(22, |_| Ok(()));
        s.commit();
        assert_eq!(s.volume.percent(), 22);
        assert!(s.dirty);
        assert!(s.error.contains("could not save"));
        assert_eq!(std::fs::read_to_string(parent).unwrap(), "keep me");
        std::fs::remove_dir_all(dir).unwrap();
    }
    #[test]
    fn bridge_rejects_invalid_inputs() {
        assert_eq!(
            action(r#"{"action":"volume","percent":0}"#),
            Some(Action::Volume(0))
        );
        assert_eq!(
            action(r#"{"action":"volume","percent":100}"#),
            Some(Action::Volume(100))
        );
        for p in ["-1", "101", "9999999", "0.5", "null", "\"40\"", "true"] {
            assert_eq!(
                action(&format!(r#"{{"action":"volume","percent":{p}}}"#)),
                None
            );
        }
        assert_eq!(action(r#"{"action":"execute"}"#), None);
    }
    #[test]
    fn failed_mute_does_not_hide_output_error_or_commit_pending_settings() {
        let mut s = State::at(None);
        s.change(33, |_| Ok(()));
        s.toggle(|_| Err("output rejected gain".into()));
        assert_eq!(s.volume.percent(), 33);
        assert!(s.error.contains("output rejected gain"));
        assert!(s.dirty);
    }
    #[test]
    fn sdl_gain_changes_already_queued_pcm_without_mutating_source() {
        use sdl3::sys::audio::*;
        struct Stream(*mut SDL_AudioStream);
        impl Drop for Stream {
            fn drop(&mut self) {
                unsafe {
                    SDL_DestroyAudioStream(self.0);
                }
            }
        }
        let spec: SDL_AudioSpec = sdl3::audio::AudioSpec {
            freq: Some(44100),
            channels: Some(2),
            format: Some(sdl3::audio::AudioFormat::s16_sys()),
        }
        .into();
        // SAFETY: standalone unbound conversion stream, no playback device/system volume.
        // SDL copies the input, and the RAII wrapper destroys the stream even on a test panic.
        unsafe {
            let stream = Stream(SDL_CreateAudioStream(&spec, &spec));
            assert!(!stream.0.is_null(), "{}", sdl3::get_error());
            let source: Vec<i16> = [8192i16, -8192, 16384, -16384]
                .into_iter()
                .cycle()
                .take(768)
                .collect();
            let before = source.clone();
            assert!(SDL_PutAudioStreamData(
                stream.0,
                source.as_ptr().cast(),
                (source.len() * 2) as i32
            ));
            assert!(SDL_FlushAudioStream(stream.0));
            for (percent, factor) in [(100, 1.0f32), (25, 0.25), (0, 0.0)] {
                let mut state = State::at(None);
                state.change(percent, |gain| {
                    if SDL_SetAudioStreamGain(stream.0, gain) {
                        Ok(())
                    } else {
                        Err(sdl3::get_error().to_string())
                    }
                });
                assert!(state.error.is_empty());
                let mut out = [0i16; 256];
                assert_eq!(
                    SDL_GetAudioStreamData(stream.0, out.as_mut_ptr().cast(), 512),
                    512
                );
                for (i, sample) in out.into_iter().enumerate() {
                    let expected = (f32::from(source[i]) * factor) as i16;
                    assert!(
                        (i32::from(sample) - i32::from(expected)).abs() <= 1,
                        "{percent}%: {sample} != {expected}"
                    );
                }
            }
            assert_eq!(source, before);
        }
    }
}
